import{_ as e,o as i,c as a,a0 as n}from"./chunks/framework.CShDTZbC.js";const u=JSON.parse('{"title":"Phase 2C: Falsification Tournament Results","description":"","frontmatter":{},"headers":[],"relativePath":"phase-2c-falsification.md","filePath":"phase-2c-falsification.md"}'),o={name:"phase-2c-falsification.md"};function r(s,t,d,l,c,h){return i(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="phase-2c-falsification-tournament-results" tabindex="-1">Phase 2C: Falsification Tournament Results <a class="header-anchor" href="#phase-2c-falsification-tournament-results" aria-label="Permalink to &quot;Phase 2C: Falsification Tournament Results&quot;">​</a></h1><h2 id="_1-decision-matrix" tabindex="-1">1. Decision Matrix <a class="header-anchor" href="#_1-decision-matrix" aria-label="Permalink to &quot;1. Decision Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Candidate</th><th>Experiment / Focus</th><th>Hypothesis</th><th>Success Criterion</th><th>Primary Metric</th><th>Ground Truth</th><th>Baseline</th><th>Result</th><th>Evidence Grade</th><th>Agent Necessity</th><th>Reproducibility</th><th>Demo</th><th>Risk</th><th>Decision</th></tr></thead><tbody><tr><td>#29 Dev Troubleshooter</td><td>Broken Dockerfile</td><td>Agent can fix env errors via terminal</td><td>App runs successfully</td><td>Time to fix / success rate</td><td>HTTP 200 OK</td><td>Google Search</td><td>SURVIVED</td><td>A</td><td>Very High</td><td>High (Docker)</td><td>10</td><td>Med</td><td><strong>🥇 FINALIST</strong></td></tr><tr><td>#11 Pentest Validator</td><td>Sandbox SQLi</td><td>Agent dynamically exploits custom vuln</td><td>Flag extracted</td><td>Verification rate</td><td>Known flag</td><td>Nessus/sqlmap</td><td>SURVIVED</td><td>A</td><td>High</td><td>High (Local VM)</td><td>9</td><td>Med</td><td><strong>🥈 FINALIST</strong></td></tr><tr><td>#7 Legacy Translator</td><td>Python -&gt; JS</td><td>Agent uses compiler feedback to fix code</td><td>Code passes tests</td><td>Test pass rate</td><td>Human test suite</td><td>Zero-shot LLM</td><td>SURVIVED</td><td>B</td><td>High</td><td>High</td><td>7</td><td>Low</td><td><strong>🥉 FINALIST</strong></td></tr><tr><td>#3 Flaky Test Diagnoser</td><td>Race condition</td><td>Agent isolates non-deterministic failure</td><td>Root cause found</td><td>Accuracy</td><td>Known bug</td><td>10x retry diff</td><td>FAILED</td><td>E</td><td>Very High</td><td><strong>Very Low</strong></td><td>2</td><td>High</td><td><strong>KILL</strong></td></tr><tr><td>#2 Dependency Analyzer</td><td>Breaking bump</td><td>Agent finds unlisted breaking change</td><td>Fix proposed</td><td>Correctness</td><td>Manual PR</td><td>Dependabot</td><td>FAILED</td><td>D</td><td>High</td><td>Low</td><td>4</td><td>High</td><td><strong>KILL</strong></td></tr><tr><td>#1 CI/CD Investigator</td><td>GH Actions break</td><td>Agent edits and pushes fix</td><td>Green build</td><td>Build status</td><td>CI Green</td><td>Log parser</td><td>FAILED</td><td>C</td><td>High</td><td>Low (Time)</td><td>3</td><td>High</td><td><strong>KILL</strong></td></tr></tbody></table><hr><h2 id="_2-candidates-we-killed-the-kill-report" tabindex="-1">2. Candidates We Killed (The Kill Report) <a class="header-anchor" href="#_2-candidates-we-killed-the-kill-report" aria-label="Permalink to &quot;2. Candidates We Killed (The Kill Report)&quot;">​</a></h2><h3 id="☠️-candidate-3-flaky-test-root-cause-diagnoser" tabindex="-1">☠️ Candidate #3: Flaky Test Root Cause Diagnoser <a class="header-anchor" href="#☠️-candidate-3-flaky-test-root-cause-diagnoser" aria-label="Permalink to &quot;☠️ Candidate #3: Flaky Test Root Cause Diagnoser&quot;">​</a></h3><ol><li><strong>Original Appeal:</strong> Huge engineering pain point, massive agentic necessity (requires running tests iteratively).</li><li><strong>Falsification Experiment:</strong> Attempt to create a synthetic flaky test that fails exactly 50% of the time for judging.</li><li><strong>What Happened:</strong> Creating a &quot;reliably flaky&quot; test is an oxymoron. Environmental differences on a judge&#39;s machine mean the test might pass 100% of the time or fail 100% of the time, ruining the demonstration of the agent isolating non-determinism.</li><li><strong>Why it Failed:</strong> It fails the Reproducibility test completely.</li><li><strong>Threatened Category:</strong> Reproducibility (15 pts), Demo Potential.</li><li><strong>Fixable?</strong> No. Flakiness is inherently tied to underlying host hardware/timing.</li></ol><h3 id="☠️-candidate-2-dependency-update-risk-analyzer" tabindex="-1">☠️ Candidate #2: Dependency Update Risk Analyzer <a class="header-anchor" href="#☠️-candidate-2-dependency-update-risk-analyzer" aria-label="Permalink to &quot;☠️ Candidate #2: Dependency Update Risk Analyzer&quot;">​</a></h3><ol><li><strong>Original Appeal:</strong> Better than Dependabot; prevents runtime breaks.</li><li><strong>Falsification Experiment:</strong> Feed the agent a breaking change that is <em>not</em> documented in the changelog, forcing it to write tests to find the break.</li><li><strong>What Happened:</strong> Writing comprehensive regression tests for third-party libraries without human context is beyond the scope of a 5-minute hackathon agent.</li><li><strong>Why it Failed:</strong> We cannot establish objective Ground Truth. If the agent says &quot;It&#39;s safe&quot;, we have no quick way to prove it&#39;s wrong in a demo.</li><li><strong>Threatened Category:</strong> Measured Improvement (15 pts), End-to-End Quality (20 pts).</li><li><strong>Fixable?</strong> Too complex for a 5-minute demonstration.</li></ol><h3 id="☠️-candidate-1-ci-cd-build-failure-investigator" tabindex="-1">☠️ Candidate #1: CI/CD Build Failure Investigator <a class="header-anchor" href="#☠️-candidate-1-ci-cd-build-failure-investigator" aria-label="Permalink to &quot;☠️ Candidate #1: CI/CD Build Failure Investigator&quot;">​</a></h3><ol><li><strong>Original Appeal:</strong> Solves a huge DevOps pain point.</li><li><strong>Falsification Experiment:</strong> Have the agent fix a GitHub Action and wait for the remote CI to pass.</li><li><strong>What Happened:</strong> Remote CI/CD takes 2-5 minutes per run. An iterative loop (e.g., 3 attempts) will take 15 minutes.</li><li><strong>Why it Failed:</strong> Kills the 5-minute demo rule entirely. We would have to heavily edit the video, looking suspicious.</li><li><strong>Threatened Category:</strong> Reproducibility (15 pts).</li><li><strong>Fixable?</strong> Only by running a local mock CI runner (e.g., <code>act</code>), which adds massive dependency overhead for the judges.</li></ol><hr><h2 id="_3-the-survivors-top-3-finalists" tabindex="-1">3. The Survivors (Top 3 Finalists) <a class="header-anchor" href="#_3-the-survivors-top-3-finalists" aria-label="Permalink to &quot;3. The Survivors (Top 3 Finalists)&quot;">​</a></h2><h3 id="🥇-finalist-1-local-dev-environment-troubleshooter-candidate-29" tabindex="-1">🥇 Finalist 1: Local Dev Environment Troubleshooter (Candidate #29) <a class="header-anchor" href="#🥇-finalist-1-local-dev-environment-troubleshooter-candidate-29" aria-label="Permalink to &quot;🥇 Finalist 1: Local Dev Environment Troubleshooter (Candidate #29)&quot;">​</a></h3><ol><li><strong>Why it survived:</strong> Unbeatable reproducibility (runs entirely inside a local Docker sandbox). Highest possible agentic necessity (terminal loops).</li><li><strong>Strongest evidence:</strong> Pass/Fail is binary. Either the Docker container starts and returns HTTP 200, or it doesn&#39;t.</li><li><strong>Biggest remaining uncertainty:</strong> Preventing the LLM from getting trapped in an infinite <code>npm cache clean</code> loop.</li><li><strong>Most dangerous criticism:</strong> &quot;It&#39;s a security nightmare that will <code>rm -rf</code> my machine.&quot;</li><li><strong>Next experiment:</strong> Build a strict command-whitelist sandbox wrapper.</li></ol><h3 id="🥈-finalist-2-security-pentest-report-validator-candidate-11" tabindex="-1">🥈 Finalist 2: Security Pentest Report Validator (Candidate #11) <a class="header-anchor" href="#🥈-finalist-2-security-pentest-report-validator-candidate-11" aria-label="Permalink to &quot;🥈 Finalist 2: Security Pentest Report Validator (Candidate #11)&quot;">​</a></h3><ol><li><strong>Why it survived:</strong> Huge &quot;wow factor&quot; demo. Highly objective ground truth (capturing a flag).</li><li><strong>Strongest evidence:</strong> The agent successfully finding a flag in a custom vulnerable local app that automated tools like Nessus might miss.</li><li><strong>Biggest remaining uncertainty:</strong> LLM context windows overflowing with huge Nmap/Curl outputs.</li><li><strong>Most dangerous criticism:</strong> &quot;It&#39;s just a slow, expensive version of sqlmap.&quot;</li><li><strong>Next experiment:</strong> Prove the agent can dynamically bypass a simple WAF that blocks sqlmap.</li></ol><h3 id="🥉-finalist-3-legacy-code-translator-verifier-candidate-7" tabindex="-1">🥉 Finalist 3: Legacy Code Translator &amp; Verifier (Candidate #7) <a class="header-anchor" href="#🥉-finalist-3-legacy-code-translator-verifier-candidate-7" aria-label="Permalink to &quot;🥉 Finalist 3: Legacy Code Translator &amp; Verifier (Candidate #7)&quot;">​</a></h3><ol><li><strong>Why it survived:</strong> Iterative compiler feedback loop is the textbook definition of agentic workflows.</li><li><strong>Strongest evidence:</strong> 100% test pass rate on the translated code.</li><li><strong>Biggest remaining uncertainty:</strong> Where does the ground truth (the test suite) come from?</li><li><strong>Most dangerous criticism:</strong> &quot;If the agent writes its own tests, it will just write tests that pass its broken translation.&quot;</li><li><strong>Next experiment:</strong> Determine if the user MUST supply the legacy test suite (which makes the product slightly less magical, but perfectly reproducible).</li></ol>',19)])])}const p=e(o,[["render",r]]);export{u as __pageData,p as default};
